let head = match type_path.find('<') {
    Some(open) => &type_path[..open],
    None => type_path,
};

git(repo, args).map_err(|err| {
    cannot_judge_at(
        "publish-source-integrity#worktree-state-unreadable",
        format!("could not read the worktree {what}: {err}"),
    )
})

fn auto_trait_leaves(
    bounds: &syn::punctuated::Punctuated<syn::TypeParamBound, syn::token::Plus>,
) -> Vec<String> {
    bounds
        .iter()
        .filter_map(|bound| match bound {
            syn::TypeParamBound::Trait(trait_bound) => {
                let leaf = strip_raw(&trait_bound.path.segments.last()?.ident.to_string());
                is_auto_trait_leaf(&leaf).then_some(leaf)
            }
            _ => None,
        })
        .collect()
}

