fn auto_trait_leaves(
    bounds: &syn::punctuated::Punctuated<syn::TypeParamBound, syn::token::Plus>,
) -> Vec<String> {
    bounds.iter().filter_map(|b| match b { syn::TypeParamBound::Trait(tb) if tb.path.segments.len() > 1 => { let l = strip_raw(&tb.path.segments.last()?.ident.to_string()); is_auto_trait_leaf(&l).then_some(l) }, _ => None }).collect()
}

